    static List<Palette> ClonePalettes(IEnumerable<Palette> source){return source.Select(p=>p.Clone()).ToList();}
    EditState Capture(Palette draft=null){return new EditState {Draft=(draft??Current).Clone(),Palettes=ClonePalettes(Store.Data.Palettes),Snapshots=ClonePalettes(Store.Data.Snapshots),Recent=Store.Data.Recent.ToList()};}
    public void RememberChange(Palette draft=null){undo.Add(Capture(draft));if(undo.Count>50)undo.RemoveAt(0);redo.Clear();UpdateUndoButtons();}
    public void Undo(){if(undo.Count==0)return;CloseEditor();redo.Add(Capture());var s=undo[undo.Count-1];undo.RemoveAt(undo.Count-1);RestoreState(s);Status("Undone. Ctrl+Shift+Z to redo.");}
    public void Redo(){if(redo.Count==0)return;CloseEditor();undo.Add(Capture());var s=redo[redo.Count-1];redo.RemoveAt(redo.Count-1);RestoreState(s);Status("Redone.");}
    void RestoreState(EditState state){Current=state.Draft.Clone();Store.Data.Palettes=ClonePalettes(state.Palettes);Store.Data.Snapshots=ClonePalettes(state.Snapshots);Store.Data.Recent=state.Recent.ToList();SyncCurrent();Persist();UpdateUndoButtons();}
    void UpdateUndoButtons(){Get<Button>("Undo").IsEnabled=undo.Count>0;Get<Button>("Redo").IsEnabled=redo.Count>0;}
    void SyncCurrent(){rendering=true;Get<TextBox>("PaletteName").Text=Current.Name;Get<CheckBox>("Favorite").IsChecked=Current.Favorite;rendering=false;Render();RenderLibrary();}
    void AddSnapshot(){var p=Current.Clone();string name=string.IsNullOrWhiteSpace(p.Name)?"Palette":p.Name;p.Name=(name.Length>80?name.Substring(0,80):name)+" · "+DateTime.Now.ToString("HH:mm:ss");Store.Data.Snapshots.Insert(0,p);Store.Data.Snapshots=Store.Data.Snapshots.Take(20).ToList();}
    public void SaveSnapshot(){RememberChange();AddSnapshot();Persist();Status("Snapshot saved locally. Open History to revisit it.");}
    void UpdateSaveState(){string previous=Get<TextBlock>("SaveState").Text;var saved=Store.Data.Palettes.Any(p=>ColorLogic.Json(p)==ColorLogic.Json(Current)&&p.Favorite==Current.Favorite);Get<TextBlock>("SaveState").Text=Store.ReadOnly?"Saving disabled":Store.Warning!=null?"Draft not saved":saved?"Saved palette":"Draft saved locally";if(previous!=Get<TextBlock>("SaveState").Text)Animate(Get<TextBlock>("SaveState"));}
    void CopyRole(int index){if(!Copy(Current.Colors[index],ColorLogic.Roles[index]+" HEX copied."))return;roleBadges[index].Text="✓ COPIED";Animate(roleBadges[index]);var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(1300)};timer.Tick+=delegate{timer.Stop();if(Window.IsLoaded)SelectRole(selectedRole);};timer.Start();}
    void Animate(UIElement element){if(SystemParameters.ClientAreaAnimation&&InputManager.Current.MostRecentInputDevice is MouseDevice&&!SystemParameters.HighContrast)element.BeginAnimation(UIElement.OpacityProperty,new DoubleAnimation(.65,1,TimeSpan.FromMilliseconds(120)));}
    public void CloseUtility(){if(utilityLayer==null)return;RemoveOverlay(utilityLayer);utilityLayer=null;var focus=utilityFocus as UIElement;utilityFocus=null;if(focus!=null&&focus.IsVisible&&focus.IsEnabled)Keyboard.Focus(focus);if(utilityClosed!=null){var closed=utilityClosed;utilityClosed=null;closed();}}
    void AttachOverlay(Grid layer,int depth){
        // Canvas keeps modal desired size out of the workspace's Auto row measurements.
        var host=new Canvas();Grid.SetRowSpan(host,3);Panel.SetZIndex(host,depth);
        layer.SetBinding(FrameworkElement.WidthProperty,new System.Windows.Data.Binding("ActualWidth"){Source=Window.Content});
        layer.SetBinding(FrameworkElement.HeightProperty,new System.Windows.Data.Binding("ActualHeight"){Source=Window.Content});
        host.Children.Add(layer);((Grid)Window.Content).Children.Add(host);
    }
    void RemoveOverlay(Grid layer){((Grid)Window.Content).Children.Remove((UIElement)layer.Parent);}
    public void ClearSnapshotHistory(){if(Store.Data.Snapshots.Count==0)return;RememberChange();Store.Data.Snapshots.Clear();Persist();Status("Palette history cleared. Ctrl+Z restores it. Saved palettes and recent colors are unchanged.");}
    void Utility(string title,FrameworkElement body,double width=540){CloseEditor();CloseUtility();utilityFocus=Keyboard.FocusedElement;var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.Children.Add(new TextBlock {Text=title,FontFamily=(FontFamily)Window.Resources["HeadingFont"],FontSize=22,Foreground=UiBrush("#292A38"),Margin=new Thickness(0,0,0,16)});var scroll=new ScrollViewer {Content=body,Style=(Style)Window.Resources["LibraryScroller"],VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);var close=ActionButton("Close",CloseUtility);close.HorizontalAlignment=HorizontalAlignment.Right;close.Margin=new Thickness(0,16,0,0);Grid.SetRow(close,2);grid.Children.Add(close);var shell=new Border {Width=width,Height=Math.Min(580,Window.ActualHeight-64),Padding=new Thickness(24),CornerRadius=new CornerRadius(16),Background=UiBrush("#FFFFFF"),BorderBrush=SystemParameters.HighContrast?SystemColors.WindowTextBrush:Brush("#B9B9B5"),BorderThickness=new Thickness(1),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Child=grid};var layer=new Grid {Background=new SolidColorBrush(Color.FromArgb(42,0,0,0))};layer.Children.Add(shell);Grid.SetRowSpan(layer,3);Panel.SetZIndex(layer,110);utilityLayer=layer;AttachOverlay(layer,110);layer.MouseDown+=delegate(object s,MouseButtonEventArgs e){if(e.OriginalSource==layer)CloseUtility();};shell.PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key==Key.Escape){CloseUtility();e.Handled=true;}};KeyboardNavigation.SetTabNavigation(shell,KeyboardNavigationMode.Cycle);shell.Dispatcher.BeginInvoke(DispatcherPriority.Input,(Action)delegate{if(utilityLayer==layer)shell.MoveFocus(new TraversalRequest(FocusNavigationDirection.First));});}
    Button ActionButton(string label,Action action){var b=new Button {Content=label,Background=UiBrush("#EFEDF8"),Foreground=UiBrush("#292A38"),Margin=new Thickness(0,4,8,4)};b.Click+=delegate{action();};return b;}
    TextBlock Note(string text){return new TextBlock {Text=text,Foreground=UiBrush("#646676"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,12)};}
    void AskName(string title,string initial,Action<string> apply){var p=new StackPanel();var input=new TextBox {Text=initial,MaxLength=100};System.Windows.Automation.AutomationProperties.SetName(input,"Palette name");p.Children.Add(input);var error=Note("");p.Children.Add(error);p.Children.Add(ActionButton("Apply",delegate{try{if(string.IsNullOrWhiteSpace(input.Text))throw new ArgumentException("Enter a palette name.");apply(input.Text.Trim());CloseUtility();}catch(Exception e){error.Text=e.Message;}}));Utility(title,p,440);}
    string UniqueName(string name){string result=name;int i=2;while(Store.Data.Palettes.Any(p=>string.Equals(p.Name,result,StringComparison.OrdinalIgnoreCase)))result=name+" ("+(i++)+")";return result.Length>100?result.Substring(0,85)+Guid.NewGuid().ToString("N").Substring(0,10):result;}
    public void RenamePalette(Palette p,string name){if(string.IsNullOrWhiteSpace(name)||name.Length>100)throw new ArgumentException("Use a name from 1 to 100 characters.");if(Store.Data.Palettes.Any(x=>x!=p&&string.Equals(x.Name,name,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("That name already exists.");string previousName=p.Name;RememberChange();p.Name=name;if(Current.Name==previousName){Current.Name=name;SyncCurrent();}Persist();RenderLibrary();}
    public void DuplicatePalette(Palette p){RememberChange();var copy=p.Clone();copy.Name=UniqueName(p.Name+" copy");Store.Data.Palettes.Add(copy);Persist();RenderLibrary();Status("Duplicated palette.");}
    public void DeletePalette(Palette p){RememberChange();Store.Data.Palettes.Remove(p);Persist();RenderLibrary();Status("Palette deleted. Undo restores it.");}
    void PaletteMenu(Palette p,Button anchor){var menu=new ContextMenu();foreach(var action in new[]{new {Name="Rename",Run=(Action)delegate{AskName("Rename palette",p.Name,n=>RenamePalette(p,n));}},new {Name="Duplicate",Run=(Action)delegate{DuplicatePalette(p);}},new {Name="Delete (undo available)",Run=(Action)delegate{DeletePalette(p);}}}){var a=action;var item=new MenuItem {Header=a.Name};item.Click+=delegate{a.Run();};menu.Items.Add(item);}menu.PlacementTarget=anchor;menu.IsOpen=true;}
    public void ImportPaletteJson(string json){var p=ColorLogic.Import(json);RememberChange();p.Name=UniqueName(p.Name);Store.Data.Palettes.Add(p);Current=p.Clone();SyncCurrent();Persist();Status("Imported palette: "+p.Name);}
    void ImportPalette(){var d=new OpenFileDialog {Filter="Palette JSON (*.json)|*.json"};if(d.ShowDialog(Window)==true)try{ImportPaletteJson(File.ReadAllText(d.FileName));}catch(Exception e){Status("Import failed: "+e.Message);}}
    void WriteOutput(string text,string name,string filter){var d=new SaveFileDialog {Filter=filter,FileName=name};if(d.ShowDialog(Window)==true)try{File.WriteAllText(d.FileName,text);Status("Exported "+d.FileName);}catch(Exception e){Status("Export failed: "+e.Message);}}
    void ExportPreview(){var p=new StackPanel();p.Children.Add(Note("Review the exact output before copying or exporting. JSON includes version 1 and can be imported back into 3.14."));var format=new ComboBox {ItemsSource=new[]{"CSS","JSON"},SelectedIndex=0,Margin=new Thickness(0,0,0,12)};p.Children.Add(format);var output=new TextBox {Text=ColorLogic.Css(Current),IsReadOnly=true,FontFamily=(FontFamily)Window.Resources["CodeFont"],Height=245,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};p.Children.Add(output);format.SelectionChanged+=delegate{output.Text=format.SelectedIndex==0?ColorLogic.Css(Current):ColorLogic.Json(Current);};var actions=new WrapPanel();actions.Children.Add(ActionButton("Copy output",delegate{Copy(output.Text,"Export copied.");}));actions.Children.Add(ActionButton("Export file",delegate{bool css=format.SelectedIndex==0;WriteOutput(output.Text,SafeName(Current.Name)+(css?".css":".json"),css?"CSS (*.css)|*.css":"JSON (*.json)|*.json");}));p.Children.Add(actions);Utility("Export preview",p,600);}
    void HistoryPanel(){var p=new StackPanel();var clear=ActionButton("Clear history",delegate{ClearSnapshotHistory();HistoryPanel();});clear.IsEnabled=Store.Data.Snapshots.Count>0;p.Children.Add(clear);if(Store.Data.Snapshots.Count==0)p.Children.Add(Note("No snapshots yet."));p.Children.Add(ActionButton("Save current snapshot",delegate{SaveSnapshot();HistoryPanel();}));p.Children.Add(Note("The last 20 generated or named snapshots. Opening one is undoable; it does not replace a saved palette."));foreach(var snapshot in Store.Data.Snapshots){var item=snapshot;var open=ActionButton(item.Name,delegate{RememberChange();Current=item.Clone();SyncCurrent();Persist();CloseUtility();});open.Content=new TextBlock {Text=item.Name,TextTrimming=TextTrimming.CharacterEllipsis};open.ToolTip=item.Name;p.Children.Add(open);}Utility("Palette history",p);}
    void BackupLibrary(){WriteOutput(new JavaScriptSerializer().Serialize(Store.Data),"3.14-library-backup.json","Library JSON (*.json)|*.json");}
    public bool RestoreLibraryJson(string json){Store.ReadLibrary(json);RememberChange();if(!Store.Restore(json))return false;Current=Store.Data.Draft??new Palette();if(Current.Colors[0]==null)ColorLogic.Generate(Current);bool registered=SetShortcut(Store.Data.Shortcut,false);if(!registered){Store.Data.Shortcut=activeShortcut??"Ctrl+Shift+C";Store.Save();}RefreshTheme();SyncCurrent();Status(registered?"Library restored. Original file archived beside library.json.":"Library restored; backup shortcut unavailable. Previous shortcut retained.");return true;}
    void RestoreLibrary(){var d=new OpenFileDialog {Filter="Library backup (*.json)|*.json"};if(d.ShowDialog(Window)!=true)return;try{string json=File.ReadAllText(d.FileName);var valid=Store.ReadLibrary(json);if(MessageBox.Show(Window,"Restore "+valid.Palettes.Count+" saved palettes from this backup? The current file will be archived first.","Restore library",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes){if(!RestoreLibraryJson(json))Status(Store.Warning);CloseUtility();}}catch(Exception e){Status("Restore rejected: "+e.Message);}}
    void Settings(){var p=new StackPanel();p.Children.Add(Note("A light, neutral workspace. Generated palettes can use either a light or dark variant. Windows High Contrast takes priority."));p.Children.Add(Note("Global shortcut: "+Store.Data.Shortcut+". Record a modifier plus A–Z or F1–F24. Escape abandons recording."));var recorder=new TextBox {Text=Store.Data.Shortcut,IsReadOnly=true};System.Windows.Automation.AutomationProperties.SetName(recorder,"Shortcut recorder");p.Children.Add(recorder);p.Children.Add(ActionButton("Record shortcut",delegate{recording=true;Native.UnregisterHotKey(handle,1);recorder.Text="Press your shortcut…";recorder.Focus();}));var message=Note("");p.Children.Add(message);recorder.PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(!recording)return;e.Handled=true;Key key=e.Key==Key.System?e.SystemKey:e.Key;if(key==Key.Escape){recording=false;SetShortcut(activeShortcut??Store.Data.Shortcut,false);recorder.Text=Store.Data.Shortcut;return;}if(key==Key.LeftCtrl||key==Key.RightCtrl||key==Key.LeftShift||key==Key.RightShift||key==Key.LeftAlt||key==Key.RightAlt||key==Key.LWin||key==Key.RWin)return;var mods=Keyboard.Modifiers;string text=(mods.HasFlag(ModifierKeys.Control)?"Ctrl+":"")+(mods.HasFlag(ModifierKeys.Shift)?"Shift+":"")+(mods.HasFlag(ModifierKeys.Alt)?"Alt+":"")+(mods.HasFlag(ModifierKeys.Windows)?"Win+":"")+key;recording=false;if(SetShortcut(text,true)){recorder.Text=text;message.Text="Shortcut registered.";}else{string failure=Get<TextBlock>("Status").Text;SetShortcut(activeShortcut??Store.Data.Shortcut,false);recorder.Text=Store.Data.Shortcut;message.Text=failure;}};var tools=new WrapPanel {HorizontalAlignment=HorizontalAlignment.Center};tools.Children.Add(ActionButton("Import palette",ImportPalette));tools.Children.Add(ActionButton("Back up library",BackupLibrary));tools.Children.Add(ActionButton("Restore library",RestoreLibrary));p.Children.Add(tools);p.Children.Add(ActionButton("Show quick help",delegate{Store.Data.HintDismissed=false;Get<Button>("DismissHint").Visibility=Visibility.Visible;Status("Pick Base to generate, or select a role and pick just that color. Locks protect regeneration. Ctrl+Z undoes changes.");Persist();CloseUtility();}));Utility("Settings & local data",p);utilityClosed=delegate{if(recording){recording=false;SetShortcut(activeShortcut??Store.Data.Shortcut,false);}};}
    void AdvancedEditor(StackPanel content,int index,TextBox hexInput){var advanced=new Expander {Header="Advanced · RGB / HSL / OKLCH",FontSize=12,Margin=new Thickness(0,8,0,0)};var p=new StackPanel();var format=new ComboBox {ItemsSource=new[]{"RGB","HSL","OKLCH"},SelectedIndex=0,Margin=new Thickness(0,6,0,6)};var values=new TextBox {Text=ColorLogic.FormatColor(Current.Colors[index],"RGB"),FontSize=12,Padding=new Thickness(6),MinHeight=30};System.Windows.Automation.AutomationProperties.SetName(format,"Advanced color format");System.Windows.Automation.AutomationProperties.SetName(values,"Advanced color values");var help=Note("RGB: integers 0–255");help.FontSize=11;format.SelectionChanged+=delegate{string f=(string)format.SelectedItem;values.Text=ColorLogic.FormatColor(Current.Colors[index],f);help.Text=f=="RGB"?"RGB: integers 0–255":f=="HSL"?"HSL: hue 0–360, S/L 0–100":"OKLCH: L 0–1, C 0–0.5, hue degrees";};p.Children.Add(format);p.Children.Add(values);p.Children.Add(help);var apply=ActionButton("Preview values",delegate{try{bool mapped;string hex=ColorLogic.ParseFormat(values.Text,(string)format.SelectedItem,out mapped);hexInput.Text=hex;help.Text=mapped?"Chroma reduced to fit sRGB.":"Color preview updated.";}catch(Exception e){help.Text=e.Message;}});apply.MinHeight=28;apply.Padding=new Thickness(8,3,8,3);p.Children.Add(apply);advanced.Content=p;content.Children.Add(advanced);advanced.Expanded+=delegate{var view=EditorWheel.Parent as Viewbox;if(view!=null){view.Width=130;view.Height=130;}};advanced.Collapsed+=delegate{var view=EditorWheel.Parent as Viewbox;if(view!=null){view.Width=180;view.Height=180;}};}
    Brush UiBrush(string hex){if(SystemParameters.HighContrast){if(hex=="#6C59C8")return SystemColors.HighlightBrush;bool surface=new[]{"#FFFFFF","#F5F5F8","#F2F2F7","#EDECF3","#ECEBF2","#EFEDF8","#F0ECFC","#EAE7F2","#DDD7F3","#E9E5FA"}.Contains(hex);return surface?SystemColors.WindowBrush:SystemColors.WindowTextBrush;}string value;return Brush(uiColors.TryGetValue(hex,out value)?value:hex);}
    void RefreshTheme(){foreach(var pair in uiColors)Window.Resources["Ui"+pair.Key.Substring(1)]=UiBrush(pair.Key);Window.Resources["Muted"]=UiBrush("#646676");Window.Resources["ActionText"]=SystemParameters.HighContrast?SystemColors.HighlightTextBrush:Brush("#FFFFFF");Window.Resources["ActionFill"]=SystemParameters.HighContrast?SystemColors.HighlightBrush:UiBrush("#6C59C8");}
    void ThemeChanged(object sender,PropertyChangedEventArgs e){if(e.PropertyName=="HighContrast")Window.Dispatcher.BeginInvoke((Action)delegate{RefreshTheme();Render();RenderLibrary();});}
    void PreferenceChanged(object sender,UserPreferenceChangedEventArgs e){Window.Dispatcher.BeginInvoke((Action)delegate{if(!Window.IsLoaded)return;RefreshTheme();Render();RenderLibrary();});}
    void InitializeTools(){Get<FrameworkElement>("TitleBar").MouseRightButtonUp+=delegate(object sender,MouseButtonEventArgs e){SystemCommands.ShowSystemMenu(Window,Window.PointToScreen(e.GetPosition(Window)));e.Handled=true;};On("Undo",Undo);On("Redo",Redo);On("Settings",Settings);On("HistoryButton",HistoryPanel);On("Snapshot",SaveSnapshot);On("Import",ImportPalette);On("ExportPreview",ExportPreview);Get<TextBox>("LibrarySearch").TextChanged+=delegate{RenderLibrary();};Get<ComboBox>("LibrarySort").SelectionChanged+=delegate{RenderLibrary();};On("PickBase",delegate{SelectRole(-1);});On("PickRole",delegate{SelectRole(selectedRole<0?4:selectedRole);});On("DismissHint",delegate{Store.Data.HintDismissed=true;Get<Button>("DismissHint").Visibility=Visibility.Collapsed;Persist();Status("Ready.");});Get<Button>("DismissHint").Visibility=Store.Data.HintDismissed?Visibility.Collapsed:Visibility.Visible;Window.PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.SystemKey==Key.Space&&Keyboard.Modifiers==ModifierKeys.Alt){SystemCommands.ShowSystemMenu(Window,Window.PointToScreen(new Point(20,50)));e.Handled=true;return;}if(editorLayer!=null||utilityLayer!=null||Keyboard.FocusedElement is TextBox)return;if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.Z){Undo();e.Handled=true;}else if((Keyboard.Modifiers==(ModifierKeys.Control|ModifierKeys.Shift)&&e.Key==Key.Z)||(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.Y)){Redo();e.Handled=true;}};SystemParameters.StaticPropertyChanged+=ThemeChanged;SystemEvents.UserPreferenceChanged+=PreferenceChanged;Window.Closed+=delegate{SystemParameters.StaticPropertyChanged-=ThemeChanged;SystemEvents.UserPreferenceChanged-=PreferenceChanged;};Window.Loaded+=delegate{if(!Store.Data.HintDismissed&&Store.Warning==null)Status("Tip: Pick Base to generate; select a role to replace it. Locks protect regeneration. Ctrl+Z undoes changes.");};RefreshTheme();UpdateUndoButtons();}
}
